const HOSTED_DOCS_EN_COPY: Readonly<Record<string, string>> = Object.freeze(Object.fromEntries(
    Object.entries(HOSTED_DOCS_JA_COPY).map(([english, japanese]) => [japanese, english]),
));

const HOSTED_DOCS_COPY_BY_LANGUAGE: Readonly<Record<ReviewedDocsLocale, Readonly<Record<string, string>>>> = Object.freeze({
    en: HOSTED_DOCS_EN_COPY,
    ja: HOSTED_DOCS_JA_COPY,
});

export const REVIEWED_DOCS_MESSAGES: readonly ReviewedDocsMessage[] = reviewedDocsMessages();

function reviewedDocsMessages(): readonly ReviewedDocsMessage[] {
    const messages = new Map<MessageId, ReviewedDocsMessage>();
    for (const [en, ja] of Object.entries(HOSTED_DOCS_JA_COPY)) {
        const id = reviewedDocsMessageId(en);
        if (!messages.has(id)) messages.set(id, Object.freeze({ id, en: en.trim(), ja }));
    }
    return Object.freeze([...messages.values()]);
}

function reviewedDocsMessageId(source: string): MessageId {
    return `${legacyDocsMessageId(source)}-${secondaryDocsHash(source)}` as MessageId;
}

function secondaryDocsHash(source: string): string {
    let hash = 5381;
    for (const character of source.trim()) hash = ((hash * 33) ^ character.codePointAt(0)!) >>> 0;
    return hash.toString(16).padStart(8, '0');
}

export function translateReviewedDocsText(value: string, locale: ReviewedDocsLocale): string {
    const parts = splitReviewedDocsText(value);
    const translated = HOSTED_DOCS_COPY_BY_LANGUAGE[locale][parts.core];
    if (!translated) return value;
    return `${parts.leading}${translated}${parts.trailing}`;
}

export function hasReviewedDocsText(value: string): boolean {
    const core = splitReviewedDocsText(value).core;
    return Boolean(HOSTED_DOCS_JA_COPY[core] ?? HOSTED_DOCS_EN_COPY[core]);
}

function splitReviewedDocsText(value: string): { leading: string; core: string; trailing: string } {
    const leadingLength = value.length - value.trimStart().length;
    const trailingStart = value.trimEnd().length;
    return {
        leading: value.slice(0, leadingLength),
        core: value.slice(leadingLength, trailingStart),
        trailing: value.slice(trailingStart),
    };
}
